.page-heading {
 align-items: flex-start;
 display: flex;
 gap: 1rem;
 justify-content: space-between;
 margin-bottom: 1.25rem;
}

.page-heading h1 {
 font-size: 1.55rem;
 letter-spacing: 0;
 margin: 0;
}

.panel,
.metric,
.form-section {
 background: var(--panel);
 border: 1px solid var(--line);
 border-radius: 8px;
 padding: 1rem;
}

.metric-label {
 color: var(--muted);
 font-size: 0.85rem;
 font-weight: 600;
 text-transform: uppercase;
}

.metric-value {
 font-size: 2rem;
 font-weight: 700;
}

.panel-heading,
.section-heading {
 align-items: center;
 display: flex;
 justify-content: space-between;
 gap: 1rem;
 margin-bottom: 0.85rem;
}

.panel-heading h2,
.form-section h2 {
 font-size: 1rem;
 font-weight: 700;
 margin: 0;
}

.filter-bar {
