 background: var(--panel);
 border: 1px solid var(--line);
 border-radius: 8px;
 display: grid;
 gap: 0.75rem;
 grid-template-columns: minmax(220px, 2fr) repeat(4, minmax(160px, 1fr)) auto;
 margin-bottom: 1rem;
 padding: 1rem;
}

.filter-actions {
 display: flex;
 gap: 0.5rem;
}

.table-actions {
 align-items: center;
 display: flex;
 gap: 0.5rem;
 justify-content: flex-end;
}

.status-badge {
 background: #e2f2ef;
 color: #134e4a;
}

.stacked-form {
 display: grid;
 gap: 1rem;
}

.checklist-check {
 background: #f8fafc;
 border: 1px solid var(--line);
 border-radius: 8px;
 min-height: 44px;
 padding: 0.65rem 0.75rem 0.65rem 2.2rem;
}

.form-actions {
 display: flex;
 gap: 0.75rem;
}

.detail-grid {
 display: grid;
 gap: 0.45rem 1rem;
 grid-template-columns: minmax(140px, 0.45fr) 1fr;
 margin: 0;
}

.detail-grid dt {
 color: var(--muted);
 font-weight: 600;
}

.detail-grid dd {
 margin: 0;
}

.subheading,

n: 0;
}

.detail-grid dt {
 color: var(--muted);
 font-weight: 600;
}

.detail-grid dd {
 margin: 0;
}

.subheading,
.group-title {
 color: var(--muted);
 font-size: 0.85rem;
 font-weight: 700;
 margin: 1rem 0 0.5rem;
 text-transform: uppercase;
}

.task-list,
.custom-field-list,
.dynamic-list {
 display: grid;
 gap: 0.5rem;
}

.task-row,
.custom-field-row {
 align-items: center;
 border-bottom: 1px solid var(--line);
 display: grid;
 gap: 0.75rem;
 grid-template-columns: auto 1fr auto;
 padding: 0.5rem 0;
}

.custom-field-row {
 grid-template-columns: 1fr auto;
}

.task-done {
 color: var(--muted);
 text-decoration: line-through;
}

.inline-add {
 display: grid;
 gap: 0.5rem;
 grid-template-columns: 1fr auto;
 margin-top: 1rem;
}

.inline-add.two-line {
 grid-template-columns: minmax(140px, 0.4fr) 1fr auto;
}

.category-grid,
.export-grid {
 display: grid;
 gap: 0.75rem;
 grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.category-tile,

id {
 display: grid;
 gap: 0.75rem;
