}

.category-tile,
.export-tile {
 border: 1px solid var(--line);
 border-radius: 8px;
 color: var(--ink);
 display: flex;
 flex-direction: column;
 gap: 0.25rem;
 justify-content: space-between;
 min-height: 82px;
 padding: 0.9rem;
 text-decoration: none;
}

.category-tile:hover,
.export-tile:hover {
 border-color: var(--accent);
}

.export-tile span {
 font-weight: 700;
}

.export-tile small {
 color: var(--muted);
}

.preserve-lines {
 white-space: pre-wrap;
}

.template-edit-form {
 max-width: 720px;
}

[data-pc-section].is-hidden {
 display: none;
}

